    "content": "İlgili derste; integral denklemler ve integral denklemlerin sınıflandırılması, Volterra ve Fredholm integral denklemleri, Diferensiyel denklemin integral denkleme, integral denklemin diferensiyel denkleme dönüştürülmesi, Sabit ve dejenere çekirdekli integral denklemler, Resolvant (çözücü çekirdek), itere çekirdek, Fredholm metodu ve Rekürans, Volterra integral denklemlerinde resolvant, Gama ve Beta fonksiyonları, Spectrum kavramı, Self-Adjoint integral operatörünün spektrumu verilir.",
    "methods": "Kuramsal anlatım, matematiksel ispat, problem çözme, bilimsel kaynak incelemesi ve çözüm tartışması.",
