    "purpose": "Bu dersin amacı, bilim dünyasında yaygın olarak kullanılan ve neredeyse bir standart hâline gelen Latex programlama dilini tanıtmak; bu dili kullanarak bilimsel dokümanlar (makale, tez, seminer, bildiri, poster, broşür, kitap, ders notu vb.) hazırlama becerisi kazandırmak ve LaTeX tabanlı yazılımlar aracılığıyla bu dokümanları daha hızlı ve verimli bir şekilde oluşturabilme yetkinliği geliştirmektir.",
    "content": "Latex’in ortaya çıkış ve gelişimi ile ilgili temel bilgiler. Latex’in bileşenleri ve kurulumu. Belge yapısı: sınıflar, başlık sayfası, bölümler ve numaralandırma, biçimlendirme komutları, tablo oluşturma, kaynak yazımı ve atıf yapma, grafik ortamı. Matematiksel formüller, teorem, önerme, alfabe, sayfa düzeni, yeni komut yazma. Beamer paketleri ile sunum hazırlama. Bazı önemli Latex paketleri ve kullanımı. Latex paketi kullanarak tez ve yayın hazırlama.",
    "methods": "Kuramsal anlatım, matematiksel ispat, problem çözme, bilimsel kaynak incelemesi ve çözüm tartışması.",
