    "level": "Tezli Yüksek Lisans",
    "code": "MAT838",
    "name": "YÜKSEK DİFERANSİYEL GEOMETRİ II",
    "type": "Seçmeli",
    "credit": 3,
    "ects": 6,
    "theory": 3,
    "practice": 0,
    "term": "Bahar",
    "instructor": "Doç. Dr. HÜLYA GÜN BOZOK",
    "purpose": "Bu dersin amacı, öğrencilerin manifold ve altmanifold kavramlarını kuramsal temelleriyle kavramalarını; bir manifold üzerinde çatı demetinin matematiksel yapısını tanıyıp ifade edebilmelerini ve yüksek mertebeden eğrilikleri hesaplayıp geometrik olarak yorumlayabilmelerini sağlamaktır. Ders ayrıca, soyut geometrik yapıları analiz etme ve ileri düzey matematiksel muhakeme geliştirme becerilerini güçlendirmeyi hedefler.",
    "content": "Çatı demetleri, indirgenmiş Riemann metriği, Vektör değerleri formlar, n-boyutlu Öklid uzayı üzerinde ortonormal çatı demeti, Bir altmanifold üzerinde çatı demetleri için temel bağıntılar, Genelleştirmeler (Bir eğrinin yüksek mertebeden eğrilikleri).",
    "methods": "Kuramsal anlatım, matematiksel ispat, problem çözme, bilimsel kaynak incelemesi ve çözüm tartışması.",
    "resources": "Dersin gerçek OBS kaynakları; güncel matematik literatürü, temel başvuru kitapları ve hakemli makaleler.",
    "sdgs": [
      "4",
      "9"
    ],
    "outcomes": [
      "Yüksek diferansiyel geometri ıı kapsamındaki ileri matematiksel kavramları açıklar.",
      "Geometri ve topoloji yaklaşımlarını karşılaştırır.",
      "Yüksek diferansiyel geometri ıı problemlerine uygun matematiksel yöntemi uygular.",
      "Yüksek diferansiyel geometri ıı sonuçlarını ispatlar ve yorumlar.",
      "Yüksek diferansiyel geometri ıı alanındaki kuramsal bağlantıları değerlendirir."
    ],
    "weeklyTopics": [
      "Çatı demetleri",
      "İndirgenmiş Riemann metriği",
      "Vektör değerleri formlar",
      "n-boyutlu Öklid uzayı üzerinde ortonormal çatı demeti",
      "Örnek soru çözümleri",
      "Bir altmanifold üzerinde çatı demetleri için temel bağıntılar",
      "Genelleştirmeler (Bir eğrinin yüksek mertebeden eğrilikleri)",
      "Eğriliklerin geometrik yorumları",
      "Yüksek diferansiyel geometri ıı: kapsam ve temel kavramlar",
      "Topolojik uzaylar",
      "Diferansiyellenebilir yapılar",
      "Eğriler ve yüzeyler",
      "Metrik ve bağlantı",
      "Eğrilik kavramları",
      "Manifoldlar"
    ],
